"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak } from "./tokens.stylex";
import { rs } from "./rs";
import { Collapsible } from "./collapsible";
import { Progress } from "./progress";
import { resolveContextPricing, type ContextPricingCatalog } from "./context-pricing";

export interface TokenUsage { inputTokens?: number; outputTokens?: number; reasoningTokens?: number; cachedInputTokens?: number }
export interface TokenPricing { inputPerMillion?: number; outputPerMillion?: number; reasoningPerMillion?: number; cacheReadPerMillion?: number; currency?: string }
export interface ContextUsageProps extends Omit<React.DetailsHTMLAttributes<HTMLDetailsElement>, "title"> {
  usedTokens: number; maxTokens?: number; usage?: TokenUsage; pricing?: TokenPricing;
  /** Optional metadata from an application-owned Tokenlens/models.dev catalog. Explicit limits and rates take precedence. */
  modelId?: string; catalog?: ContextPricingCatalog;
  model?: string; label?: string; defaultOpen?: boolean;
}
const styles = stylex.create({
  root: { width: "100%", minWidth: 0, color: vlak.ink },
  body: { display: "grid", gap: "0.75rem" },
  metadata: { margin: 0, fontSize: vlak.controlLabel, color: vlak.gray, lineHeight: 1.45 },
  list: { margin: 0, display: "grid", gap: "0.5rem", fontSize: vlak.controlFs, fontVariantNumeric: "tabular-nums", lineHeight: 1.45 },
  row: { display: "flex", flexWrap: "wrap", justifyContent: "space-between", gap: "0.5rem 1rem" },
  value: { margin: 0, color: vlak.ink },
});
const valid = (value: number | undefined): value is number => value !== undefined && Number.isFinite(value) && value >= 0;
const amount = (value: number | undefined) => valid(value) ? value.toLocaleString("en-US") : "Unavailable";

/** Context occupancy and caller-supplied token usage/pricing. No model catalog or prices are fetched. */
export const ContextUsage = React.forwardRef<HTMLDetailsElement, ContextUsageProps>(function ContextUsage({ usedTokens, maxTokens: explicitLimit, usage, pricing: explicitPricing, model: explicitModel, modelId, catalog, label = "Context usage", defaultOpen = false, className, style, ...props }, ref) {
  const resolved = React.useMemo(() => modelId && catalog ? resolveContextPricing(modelId, catalog, { inputTokens: usage?.inputTokens }) : undefined, [modelId, catalog, usage?.inputTokens]);
  const maxTokens = explicitLimit ?? resolved?.maxTokens;
  const pricing = explicitPricing ?? resolved?.pricing;
  const model = explicitModel ?? resolved?.model ?? modelId;
  const known = valid(usedTokens) && valid(maxTokens) && maxTokens > 0;
  const percentage = known ? Math.round(usedTokens / maxTokens * 100) : undefined;
  const cached = usage?.cachedInputTokens;
  const reasoning = usage?.reasoningTokens;
  const input = usage?.inputTokens;
  const output = usage?.outputTokens;
  // Cached input is a subset of input; reasoning is a subset of output. Optional separate rates replace their parent rates.
  const buckets = [
    { count: input, rate: pricing?.inputPerMillion, subset: cached, subsetRate: pricing?.cacheReadPerMillion },
    { count: output, rate: pricing?.outputPerMillion, subset: reasoning, subsetRate: pricing?.reasoningPerMillion },
  ];
  let cost: number | undefined;
  if (pricing && buckets.every(bucket => valid(bucket.count) && (bucket.rate === undefined || valid(bucket.rate)) && (bucket.subsetRate === undefined || valid(bucket.subsetRate)) && (bucket.count === 0 || valid(bucket.rate)) && (bucket.subset === undefined || (valid(bucket.subset) && bucket.subset <= bucket.count)) && (bucket.count === 0 || bucket.subsetRate === undefined || bucket.subsetRate === bucket.rate || valid(bucket.subset)))) {
    cost = buckets.reduce((sum, bucket) => {
      const count = bucket.count!; const subset = valid(bucket.subset) && valid(bucket.subsetRate) ? bucket.subset : 0;
      return sum + ((count - subset) * (bucket.rate ?? 0) + subset * (bucket.subsetRate ?? 0)) / 1_000_000;
    }, 0);
    if (!Number.isFinite(cost)) cost = undefined;
  }
  const money = cost === undefined ? "Unavailable" : `${cost.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 6 })} ${pricing?.currency?.trim() || "USD"}`;
  const root = rs(["rs-context-usage", className], styles.root);
  const body = rs(["rs-context-usage-body"], styles.body);
  const metadata = rs(["rs-context-usage-metadata"], styles.metadata);
  const list = rs(["rs-context-usage-list"], styles.list);
  const row = rs(["rs-context-usage-row"], styles.row);
  const value = rs(["rs-context-usage-value"], styles.value);
  const stats = [{ label: "Input tokens", value: amount(input) }, { label: "Output tokens", value: amount(output) }, { label: "Reasoning tokens", value: amount(reasoning) }, { label: "Cached input tokens", value: amount(cached) }];
  return <Collapsible {...props} ref={ref} title={`${label}${percentage === undefined ? "" : ` · ${percentage}%`}`} defaultOpen={defaultOpen} className={root.className} style={{ ...root.style, ...style }}>
    <div {...body}>{model && <p {...metadata}>{model}</p>}{known ? <Progress value={usedTokens} max={maxTokens} label={`${amount(usedTokens)} of ${amount(maxTokens)} tokens`} /> : <p {...metadata}>Context limit unavailable.</p>}
      {known && usedTokens > maxTokens && <p {...metadata}>The supplied usage exceeds this context limit.</p>}
      {usage && <dl {...list}>{stats.map(item => <div {...row} key={item.label}><dt>{item.label}</dt><dd {...value}>{item.value}</dd></div>)}</dl>}
      {pricing && <div {...row}><span {...metadata}>Estimated cost from supplied rates</span><span {...value}>{money}</span></div>}
    </div>
  </Collapsible>;
});

import type { TokenPricing } from "./context-usage";

/** Tokenlens/models.dev catalog rates are USD per one million tokens. */
export interface ContextModelCost {
  input?: number; output?: number; reasoning?: number; cache_read?: number;
}
export interface ContextModelPricing {
  id?: string; name?: string;
  cost?: ContextModelCost & {
    tiers?: readonly (ContextModelCost & { tier: { type?: "context"; size: number } })[];
    context_over_200k?: ContextModelCost;
  };
  limit?: { context?: number; input?: number; output?: number };
}
/** Structurally accepts a supplied Tokenlens or models.dev provider catalog. */
export type ContextPricingCatalog = Readonly<Record<string, { id?: string; models: Readonly<Record<string, ContextModelPricing>> }>>;
export interface ResolvedContextPricing { modelId: string; model: string; maxTokens?: number; pricing?: TokenPricing }
export interface ContextPricingOptions { inputTokens?: number }

const valid = (value: number | undefined): value is number => typeof value === "number" && Number.isFinite(value) && value >= 0;
const normalizedId = (value: string) => value.trim().replace(/^([^/:]+):/, "$1/");

function rates(model: ContextModelPricing, inputTokens: number | undefined): TokenPricing | undefined {
  const cost = model.cost;
  if (!cost) return undefined;
  let selected: ContextModelCost = cost;
  const tiers = cost.tiers?.length ? cost.tiers : cost.context_over_200k ? [{ ...cost.context_over_200k, tier: { size: 200_000 } }] : [];
  if (tiers.length) {
    // Choosing a tier requires the actual input count, not output or estimated context occupancy.
    if (!valid(inputTokens) || tiers.some(entry => !valid(entry.tier.size) || (entry.tier.type !== undefined && entry.tier.type !== "context"))) return {};
    const thresholds = new Set(tiers.map(entry => entry.tier.size));
    if (thresholds.size !== tiers.length) return {};
    const tier = [...tiers].sort((a, b) => b.tier.size - a.tier.size).find(entry => inputTokens > entry.tier.size);
    if (tier) selected = tier;
  }
  if ([selected.input, selected.output, selected.reasoning, selected.cache_read].some(value => value !== undefined && !valid(value))) return {};
  return {
    inputPerMillion: valid(selected.input) ? selected.input : undefined,
    outputPerMillion: valid(selected.output) ? selected.output : undefined,
    reasoningPerMillion: valid(selected.reasoning) ? selected.reasoning : undefined,
    cacheReadPerMillion: valid(selected.cache_read) ? selected.cache_read : undefined,
    currency: "USD",
  };
}

/**
 * Resolve cached catalog metadata without fetching, timers, or a bundled pricing snapshot.
 * Qualified provider/model ids select the provider's prices; providerless ids must be unique.
 * Catalogs may be obtained with Tokenlens or models.dev in application/server code.
 */
export function resolveContextPricing(modelId: string, catalog: ContextPricingCatalog, options: ContextPricingOptions = {}): ResolvedContextPricing | undefined {
  const requested = normalizedId(modelId);
  if (!requested) return undefined;
  const matches: { modelId: string; model: ContextModelPricing }[] = [];
  for (const [providerKey, provider] of Object.entries(catalog)) {
    const providerIds = [providerKey, provider.id].filter((id): id is string => Boolean(id));
    for (const [modelKey, model] of Object.entries(provider.models)) {
      const localIds = [modelKey, model.id].filter((id): id is string => Boolean(id)).map(normalizedId);
      const aliases = new Set(localIds.flatMap(id => providerIds.map(providerId => id.startsWith(`${providerId}/`) ? id : `${providerId}/${id}`)));
      // A providerless lookup can be convenient, but cannot silently choose reseller pricing.
      const providerless = !requested.includes("/") && localIds.some(id => id === requested || providerIds.some(providerId => id === `${providerId}/${requested}`));
      if (aliases.has(requested) || providerless) {
        const providerId = provider.id || providerKey;
        const localId = normalizedId(model.id || modelKey);
        matches.push({ modelId: localId.startsWith(`${providerId}/`) ? localId : `${providerId}/${localId}`, model });
      }
    }
  }
  if (matches.length !== 1) return undefined;
  const found = matches[0]!;
  const limit = found.model.limit?.context;
  return { modelId: found.modelId, model: found.model.name?.trim() || found.modelId, maxTokens: valid(limit) && limit > 0 ? limit : undefined, pricing: rates(found.model, options.inputTokens) };
}

